/**
 * dsh-schedule-panel —— browser 半区。
 *
 * 在设置页（> 插件）注册「定时任务」页签（slot: settings.plugin.item），
 * 提供：选择触发时间、派发多个定时任务、查看状态/下次运行/运行结果，并能在
 * 任务运行时轮询其会话内容做实时预览。所有数据经 GET/POST /dsh-schedule-panel/*。
 *
 * 设置页插件卡（ConfigurablePluginsTab）会直接遍历各插件注册到
 * `settings.plugin.item` 的卡并渲染为 `<ul className="cards">` 的直接子项，
 * 因此本卡以 `<li className="lc-settings-card">` 呈现（带头部 + 内容区）。
 * 本卡为“功能型”：全部数据来自 HTTP，不依赖 settingsScope 的值，故无需绑定
 * settingsScope。
 */
import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client';
export declare const name = "schedule-panel-client";
/**
 * 本插件在设置页的导航项 id，必须与 Host 侧注册的 settings namespace
 *（`SETTINGS_NAMESPACE = 'dsh-schedule-panel'`）完全一致，卡才能出现在设置页。
 */
export declare const ID = "dsh-schedule-panel";
/** 本客户端模块注入的服务：settings.plugin.item 槽位由 ui-settings-slots 提供。 */
export declare const inject: string[];
/** 任务视图（来自服务端）。 */
export interface TaskView {
    id: string;
    cron: string;
    prompt: string;
    description?: string;
    cwd?: string;
    enabled: boolean;
    createdAt: number;
    lastRunAt?: number;
    lastStatus?: 'success' | 'error';
    lastError?: string;
    lastDurationMs?: number;
    runCount: number;
    failCount: number;
    running: boolean;
    nextRunAt: number | null;
    /** 运行中实时累积的会话文本（用于实时预览）。 */
    preview?: string;
}
/** 重复频率：每天 / 工作日（周一至周五）/ 周末（周六、日）。 */
export type ScheduleFrequency = 'daily' | 'weekdays' | 'weekends';
/** 新增任务的表单字段。`time` + `frequency` 实时拼成 `cron` 后再提交。 */
export interface NewTaskForm {
    /** 用户选择的时间（"HH:MM"），来自 <input type="time">。 */
    time: string;
    /** 重复频率。 */
    frequency: ScheduleFrequency;
    /** 由 time + frequency 拼出的 5 段 cron（提交用，保持与 Host 契约一致）。 */
    cron: string;
    prompt: string;
    description: string;
}
/** 由选择的时间（HH:MM）+ 重复频率拼出 5 段 cron（分 时 日 月 周）。
 *  分钟与小时来自选择，日恒为 `*`；周字段按频率取 `*`（每天）/ `1-5`（工作日）/ `0,6`（周末）。
 */
export declare function cronFromTime(time: string, frequency: ScheduleFrequency): string;
/**
 * 设置页注册：在「插件」分区向 `settings.plugin.item` 注册本卡，
 * `key` 必须等于 Host 侧注册的 settings namespace（`ID`）。
 *
 * 运行时 `ConfigurablePluginsTabController` 取“Host 已服务的命名空间”与
 * “本卡登记的 `key`”的交集来决定展示哪些卡——因此这里的 `key` 与 Host 的
 * `SETTINGS_NAMESPACE` 配对，卡就出现在设置页，无需绑定 settingsScope。
 */
export declare function apply(ctx: ClientContext): void;
